const defaults = { handedness:'right',buttonSize:1,opacity:0.85,stickSensitivity:1,deadzone:0.12,aimSensitivity:1,invertAim:false,reducedMotion:false,reducedFlash:false,mute:false,dynamicRange:'night',quality:'auto' };
export function readSettings(){try{return {...defaults,...JSON.parse(localStorage.getItem('moonfall.settings')||'{}')}}catch{return {...defaults}}}
export function saveSettings(settings){try{localStorage.setItem('moonfall.settings',JSON.stringify(settings))}catch{} window.dispatchEvent(new CustomEvent('moonfall:settings',{detail:settings}));}
export function createControls(element=document.body){
 const settings=readSettings(),keys=new Set(),pointers=new Map(),abort=new AbortController(),opts={signal:abort.signal}; let active=false,editing=false,stick={x:0,y:0},aim={x:0,y:0},aimPoint=null,mouseFire=false;
 const root=document.createElement('div');root.id='flight-controls'; root.innerHTML=`<div id="aim-zone" aria-label="Drag to aim"></div><div id="flight-stick" data-layout="stick" role="group" aria-label="Flight direction"><span class="stick-cross"></span><i></i><small>STEER</small></div><button class="flight-button fire" data-action="fire" data-layout="fire" aria-label="Fire cannon">FIRE<span>CANNON</span></button><button class="flight-button missile" data-action="missile" data-layout="missile" aria-label="Hold to lock missile, release to launch">MISSILE<span>HOLD / LOCK</span></button><button class="flight-button boost" data-action="boost" data-layout="boost">BOOST</button><button class="flight-button brake" data-action="brake" data-layout="brake">BRAKE</button><button class="flight-button altitude-up" data-action="up" data-layout="up" aria-label="Ascend">ALT +</button><button class="flight-button altitude-down" data-action="down" data-layout="down" aria-label="Descend">ALT −</button><button class="flight-button counter" data-action="countermeasure" data-layout="countermeasure" aria-label="Deploy countermeasure">FLARE</button>`;element.append(root);
 let layout={};try{layout=JSON.parse(localStorage.getItem('moonfall.layout')||'{}')}catch{}
 function overlap(a,b,gap=5){return a.left<b.right+gap&&a.right>b.left-gap&&a.top<b.bottom+gap&&a.bottom>b.top-gap}
 function apply(){document.documentElement.style.setProperty('--control-scale',Number(settings.buttonSize)||1);document.documentElement.style.setProperty('--control-opacity',Number(settings.opacity)||.85);root.classList.toggle('left-handed',settings.handedness==='left');document.body.classList.toggle('reduced-motion',!!settings.reducedMotion);document.body.classList.toggle('reduced-flash',!!settings.reducedFlash);const nodes=[...root.querySelectorAll('[data-layout]')],w=root.clientWidth||innerWidth,h=root.clientHeight||innerHeight;for(const node of nodes){const p=layout[node.dataset.layout];if(p){p.x=Math.max(12/w,Math.min((w-node.offsetWidth-12)/w,p.x));p.y=Math.max(12/h,Math.min((h-node.offsetHeight-12)/h,p.y))}node.style.left=p?`${p.x*100}%`:'';node.style.top=p?`${p.y*100}%`:'';node.style.right=p?'auto':'';node.style.bottom=p?'auto':'';}const bad=nodes.find(n=>layout[n.dataset.layout]&&nodes.some(other=>other!==n&&overlap(n.getBoundingClientRect(),other.getBoundingClientRect())));if(bad){delete layout[bad.dataset.layout];apply()}}

 function release(){keys.clear();pointers.clear();mouseFire=false;stick={x:0,y:0};aim={x:0,y:0};aimPoint=null;root.querySelector('#flight-stick i').style.transform='translate(-50%,-50%)';root.querySelectorAll('.pressed').forEach(n=>n.classList.remove('pressed'));}
 function on(target,event,fn){target.addEventListener(event,fn,opts)}
 function point(e){const r=root.querySelector('#flight-stick').getBoundingClientRect(),radius=r.width*.37;stick.x=Math.max(-1,Math.min(1,(e.clientX-r.left-r.width/2)/radius));stick.y=Math.max(-1,Math.min(1,-(e.clientY-r.top-r.height/2)/radius));const mag=Math.hypot(stick.x,stick.y);if(mag>1){stick.x/=mag;stick.y/=mag}root.querySelector('#flight-stick i').style.transform=`translate(calc(-50% + ${stick.x*radius}px),calc(-50% - ${stick.y*radius}px))`;}
 on(root,'pointerdown',e=>{const n=e.target.closest('[data-action],#flight-stick,#aim-zone');if(!n||(!active&&!editing))return;e.preventDefault();n.setPointerCapture(e.pointerId);if(editing){const node=e.target.closest('[data-layout]');if(node)pointers.set(e.pointerId,{type:'edit',node,dx:e.clientX-node.getBoundingClientRect().left,dy:e.clientY-node.getBoundingClientRect().top});return}let type=n.dataset.action|| (n.id==='flight-stick'?'stick':'aim');if(type==='stick'&&[...pointers.values()].some(p=>p.type==='stick'))return;pointers.set(e.pointerId,{type,node:n});n.classList.add('pressed');if(type==='stick')point(e);if(type==='aim'){aimPoint={x:e.clientX,y:e.clientY};aim={x:(e.clientX-innerWidth/2)/innerWidth,y:-(e.clientY-innerHeight/2)/innerHeight}}});
 on(root,'pointermove',e=>{const p=pointers.get(e.pointerId);if(!p)return;e.preventDefault();if(p.type==='edit'){const r=root.getBoundingClientRect(),w=r.width,h=r.height,node=p.node,x=Math.max(12,Math.min(w-node.offsetWidth-12,e.clientX-r.left-p.dx)),y=Math.max(12,Math.min(h-node.offsetHeight-12,e.clientY-r.top-p.dy)),candidate={left:r.left+x,top:r.top+y,right:r.left+x+node.offsetWidth,bottom:r.top+y+node.offsetHeight};if(![...root.querySelectorAll('[data-layout]')].some(other=>other!==node&&overlap(candidate,other.getBoundingClientRect()))){layout[node.dataset.layout]={x:x/w,y:y/h};apply()}}else if(p.type==='stick')point(e);else if(p.type==='aim'){aimPoint={x:e.clientX,y:e.clientY};aim={x:(e.clientX-innerWidth/2)/innerWidth,y:-(e.clientY-innerHeight/2)/innerHeight}};});
 function up(e){const p=pointers.get(e.pointerId);if(!p)return;p.node.classList.remove('pressed');if(p.type==='stick'){stick={x:0,y:0};p.node.querySelector('i').style.transform='translate(-50%,-50%)'}pointers.delete(e.pointerId);if(editing)try{localStorage.setItem('moonfall.layout',JSON.stringify(layout))}catch{}}
 on(root,'pointerup',up);on(root,'pointercancel',up);on(root,'lostpointercapture',up);
 const gameKeys=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyQ','KeyE','Space','ShiftLeft','ShiftRight','ControlLeft','ControlRight','KeyM','KeyX'];
 on(window,'keydown',e=>{if(!active||editing||e.target.matches('input,select,textarea'))return;if(gameKeys.includes(e.code)){e.preventDefault();keys.add(e.code)}});on(window,'keyup',e=>keys.delete(e.code));
 const canvas=document.getElementById('game');if(canvas){on(canvas,'pointermove',e=>{if(e.pointerType==='mouse'){aimPoint={x:e.clientX,y:e.clientY};aim={x:(e.clientX-innerWidth/2)/innerWidth,y:-(e.clientY-innerHeight/2)/innerHeight}}});on(canvas,'pointerdown',e=>{if(active&&e.pointerType==='mouse'&&e.button===0){mouseFire=true;canvas.setPointerCapture(e.pointerId)}});on(canvas,'pointerup',()=>mouseFire=false);on(canvas,'pointercancel',()=>mouseFire=false);on(canvas,'lostpointercapture',()=>mouseFire=false);on(canvas,'contextmenu',e=>e.preventDefault())}
 on(window,'resize',()=>{apply();if(innerHeight>innerWidth)window.dispatchEvent(new CustomEvent('moonfall:portrait'))});on(window,'blur',release);on(document,'visibilitychange',()=>{if(document.hidden)release()});on(window,'moonfall:phase',e=>{active=e.detail==='playing';release();root.classList.toggle('inactive',!active&&!editing)});on(window,'moonfall:settings',e=>{Object.assign(settings,e.detail);apply()});on(window,'moonfall:layout',e=>{editing=e.detail==='edit';if(e.detail==='reset'){layout={};try{localStorage.removeItem('moonfall.layout')}catch{}apply()}release();root.classList.toggle('editing',editing);root.classList.toggle('inactive',!active&&!editing)});apply();root.classList.add('inactive');
 const held=action=>[...pointers.values()].some(p=>p.type===action),dead=(v,d=settings.deadzone)=>Math.abs(v)<d?0:Math.sign(v)*(Math.abs(v)-d)/(1-d);
 return {settings,root,release,sample(){if(!active||editing)return {moveX:0,moveY:0,aimX:aim.x,aimY:aim.y,altitude:0,fire:false,missile:false,boost:false,brake:false,countermeasure:false};let pad;try{pad=Array.from(navigator.getGamepads?.()||[]).find(Boolean)}catch{}const b=i=>!!pad?.buttons[i]?.pressed;let mx=stick.x+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+dead(pad?.axes[0]||0),my=stick.y+(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-dead(pad?.axes[1]||0);mx=dead(Math.max(-1,Math.min(1,mx)))*settings.stickSensitivity;my=dead(Math.max(-1,Math.min(1,my)))*settings.stickSensitivity;const ax=dead(pad?.axes[2]||0),ay=-dead(pad?.axes[3]||0);if(ax||ay){aim={x:ax,y:ay};aimPoint=null;}const mag=Math.hypot(aim.x,aim.y)||1;return {aimPoint,moveX:Math.max(-1,Math.min(1,mx)),moveY:Math.max(-1,Math.min(1,my)),aimX:aim.x/mag*settings.aimSensitivity,aimY:aim.y/mag*settings.aimSensitivity*(settings.invertAim?-1:1),altitude:(keys.has('KeyE')||held('up')||b(5)?1:0)-(keys.has('KeyQ')||held('down')||b(4)?1:0),fire:mouseFire||keys.has('Space')||held('fire')||b(7),missile:keys.has('KeyM')||held('missile')||b(6),boost:keys.has('ShiftLeft')||keys.has('ShiftRight')||held('boost')||b(0),brake:keys.has('ControlLeft')||keys.has('ControlRight')||held('brake')||b(1),countermeasure:keys.has('KeyX')||held('countermeasure')||b(2)}},dispose(){abort.abort();release();root.remove()}};
}
